CAT = "panceDerm"; SEG = "DER"
Q = [
("A biopsy confirms melanoma. Which feature is the most important prognostic factor for a localized tumor?",
 "Breslow thickness", ["Diameter of the lesion", "Number of colors", "Patient age"],
 "Breslow depth, measured in millimeters, guides staging, margins and sentinel node biopsy for localized melanoma; ulceration also matters. Size and color help with recognition but not prognosis."),
('A 70-year-old golfer has rough, scaly, sandpaper-like papules on the scalp and backs of the hands. Which lesion can progress to squamous cell carcinoma?',
 'Actinic keratosis', ['Basal cell carcinoma', 'Nummular eczema', 'Lentigo maligna'],
 'Actinic keratoses are sun-induced precancers that can become squamous cell carcinoma, and are treated with cryotherapy or topical 5-fluorouracil. Lentigo maligna is an early melanoma, not an SCC precursor.'),
("A 34-year-old has well-defined red plaques with silvery scale on the elbows and knees, and pinpoint bleeding when the scale is removed. What is the diagnosis?",
 "Plaque psoriasis", ["Atopic dermatitis", "Tinea corporis", "Lichen planus"],
 "Silvery-scaled plaques on extensor surfaces with the Auspitz sign are plaque psoriasis. Atopic dermatitis favors flexures, and tinea has an active scaly border with central clearing."),
("A 6-year-old has a scaly patch of hair loss with broken hairs and an enlarged occipital lymph node. What is the treatment?",
 "Oral griseofulvin", ["Topical clotrimazole", "Topical mupirocin", "Selenium shampoo alone"],
 "Tinea capitis needs an oral antifungal, such as griseofulvin or terbinafine, because topical agents do not reach the hair shaft. Antifungal shampoo is used only alongside to limit spread."),
("A 5-year-old has a few honey-colored crusted sores around the nose and mouth. What is the treatment?",
 "Topical mupirocin", ["Oral clindamycin", "Topical hydrocortisone", "Oral acyclovir"],
 "Limited nonbullous impetigo, caused by staph or strep, is treated with topical mupirocin or retapamulin. Oral antibiotics are used for widespread disease or outbreaks."),
("Two weeks after starting lamotrigine, a patient has fever, painful mucosal ulcers and a dusky rash with skin detachment over 6% of the body. What is the diagnosis?",
 "Stevens-Johnson syndrome", ["Toxic epidermal necrolysis", "Erythema multiforme minor", "Staphylococcal scalded skin"],
 "Epidermal detachment of under 10% of body surface area is Stevens-Johnson syndrome, and over 30% is toxic epidermal necrolysis. The causative drug is stopped at once."),
("A 72-year-old has several waxy, brown plaques with a stuck-on look on the back. What are these lesions?",
 "Seborrheic keratoses", ["Nodular melanomas", "Actinic keratoses", "Dermatofibromas"],
 "Seborrheic keratoses are benign, waxy, stuck-on plaques common with age and need no treatment. A sudden eruption of many may signal internal malignancy (Leser-Trelat sign)."),
('An adult has partial-thickness burns of the whole left leg and the whole back of the trunk. By the rule of nines, about what percentage of body surface is burned?',
 '36%', ['18%', '27%', '45%'],
 'In an adult each leg is 18% and the back of the trunk is 18%, so 18 + 18 = 36%. Superficial (first-degree) burns are not counted when sizing for fluid resuscitation.'),
]
